-- pos-price: Flyway baseline (flattened 2026-09-09 from the previous migration history) with the
-- ADR-0062 tenancy schema folded in. Generated by scripts/db/tenancy/flatten.py from a pg_dump of a
-- database migrated with the retired scripts; the tenancy additions are mechanical and are listed in
-- docs/TENANCY_SCHEMA.md. Global (unscoped) tables: src/main/resources/db/tenancy-global-tables.txt.
--
-- Tenant context: app_current_tenant() reads the session setting app.current_tenant, which the
-- TenantAwareDataSource (pos-tenancy-common, plan WS1) binds per checkout. Until then the owner role
-- carries a transitional default (postgres/init-tenancy.sh) and tests set it per connection.
-- With nothing bound: NULL -> every scoped table reads as empty and refuses inserts (fail closed).

-- Functions are emitted before the tables they reference (pg_dump order); do not validate bodies.
SET check_function_bodies = false;

CREATE OR REPLACE FUNCTION public.app_current_tenant() RETURNS uuid
    LANGUAGE sql STABLE PARALLEL SAFE
    AS $$ SELECT NULLIF(current_setting('app.current_tenant', true), '')::uuid $$;

CREATE TABLE public.customer_tier_pricing_rule (
    tenant_id uuid DEFAULT public.app_current_tenant() NOT NULL,
    discount_rate numeric(5,4) NOT NULL,
    created_at timestamp(6) with time zone NOT NULL,
    effective_from timestamp(6) with time zone NOT NULL,
    effective_to timestamp(6) with time zone,
    updated_at timestamp(6) with time zone NOT NULL,
    customer_tier_id uuid NOT NULL,
    id uuid NOT NULL,
    product_id uuid NOT NULL
);

CREATE TABLE public.labor_rate (
    tenant_id uuid DEFAULT public.app_current_tenant() NOT NULL,
    id uuid NOT NULL,
    location_id uuid,
    operation_category character varying(32),
    currency character varying(3) NOT NULL,
    hourly_rate numeric(10,4) NOT NULL,
    effective_from timestamp with time zone NOT NULL,
    effective_to timestamp with time zone,
    created_at timestamp with time zone NOT NULL,
    updated_at timestamp with time zone NOT NULL,
    CONSTRAINT ck_labor_rate_category CHECK (((operation_category IS NULL) OR ((operation_category)::text = ANY ((ARRAY['REPAIR'::character varying, 'DIAGNOSTIC'::character varying, 'MAINTENANCE'::character varying, 'TIRE_SERVICE'::character varying])::text[])))),
    CONSTRAINT ck_labor_rate_positive CHECK ((hourly_rate > (0)::numeric)),
    CONSTRAINT ck_labor_rate_window CHECK (((effective_to IS NULL) OR (effective_to > effective_from)))
);

CREATE TABLE public.labor_rate_adjustment (
    tenant_id uuid DEFAULT public.app_current_tenant() NOT NULL,
    id uuid NOT NULL,
    location_id uuid,
    operation_category character varying(32),
    adjustment_code character varying(64) NOT NULL,
    description character varying(255),
    adjustment_type character varying(16) NOT NULL,
    adjustment_value numeric(10,4) NOT NULL,
    sequence integer NOT NULL,
    effective_from timestamp with time zone NOT NULL,
    effective_to timestamp with time zone,
    created_at timestamp with time zone NOT NULL,
    updated_at timestamp with time zone NOT NULL,
    CONSTRAINT ck_lra_category CHECK (((operation_category IS NULL) OR ((operation_category)::text = ANY ((ARRAY['REPAIR'::character varying, 'DIAGNOSTIC'::character varying, 'MAINTENANCE'::character varying, 'TIRE_SERVICE'::character varying])::text[])))),
    CONSTRAINT ck_lra_type CHECK (((adjustment_type)::text = ANY ((ARRAY['PERCENT'::character varying, 'FIXED'::character varying])::text[]))),
    CONSTRAINT ck_lra_window CHECK (((effective_to IS NULL) OR (effective_to > effective_from)))
);

CREATE TABLE public.location_price_override (
    tenant_id uuid DEFAULT public.app_current_tenant() NOT NULL,
    currency character varying(3) NOT NULL,
    override_price numeric(10,4) NOT NULL,
    created_at timestamp(6) with time zone NOT NULL,
    effective_from timestamp(6) with time zone NOT NULL,
    effective_to timestamp(6) with time zone,
    updated_at timestamp(6) with time zone NOT NULL,
    id uuid NOT NULL,
    location_id uuid NOT NULL,
    product_id uuid NOT NULL
);

CREATE TABLE public.pricing_snapshot (
    tenant_id uuid DEFAULT public.app_current_tenant() NOT NULL,
    quantity integer NOT NULL,
    created_at timestamp(6) with time zone NOT NULL,
    updated_at timestamp(6) with time zone NOT NULL,
    snapshot_id uuid NOT NULL,
    applied_rules text,
    item_identifier character varying(255) NOT NULL,
    policy_version character varying(255) NOT NULL,
    prices text NOT NULL,
    source_context text
);

CREATE TABLE public.product_base_price (
    tenant_id uuid DEFAULT public.app_current_tenant() NOT NULL,
    currency character varying(3) NOT NULL,
    msrp numeric(10,4) NOT NULL,
    created_at timestamp(6) with time zone NOT NULL,
    effective_from timestamp(6) with time zone NOT NULL,
    effective_to timestamp(6) with time zone,
    updated_at timestamp(6) with time zone NOT NULL,
    product_id uuid NOT NULL,
    id uuid NOT NULL
);

CREATE TABLE public.promotion_eligibility_rule (
    tenant_id uuid DEFAULT public.app_current_tenant() NOT NULL,
    created_at timestamp(6) with time zone,
    updated_at timestamp(6) with time zone,
    promotion_id uuid NOT NULL,
    rule_id uuid NOT NULL,
    condition_type character varying(50) NOT NULL,
    created_by character varying(255),
    operator character varying(50) NOT NULL,
    rule_combination character varying(10),
    rule_value character varying(255) NOT NULL,
    updated_by character varying(255),
    CONSTRAINT promotion_eligibility_rule_condition_type_check CHECK (((condition_type)::text = ANY ((ARRAY['ACCOUNT_ID_LIST'::character varying, 'VEHICLE_TAG'::character varying, 'ACCOUNT_FLEET_SIZE'::character varying, 'AUDIENCE_TYPE'::character varying, 'CAMPAIGN_CODE'::character varying])::text[]))),
    CONSTRAINT promotion_eligibility_rule_operator_check CHECK (((operator)::text = ANY (ARRAY[('IN'::character varying)::text, ('NOT_IN'::character varying)::text, ('EQUALS'::character varying)::text, ('GREATER_THAN_OR_EQUAL_TO'::character varying)::text]))),
    CONSTRAINT promotion_eligibility_rule_rule_combination_check CHECK (((rule_combination)::text = ANY (ARRAY[('AND'::character varying)::text, ('OR'::character varying)::text])))
);

CREATE TABLE public.promotion_offer (
    tenant_id uuid DEFAULT public.app_current_tenant() NOT NULL,
    discount_value numeric(10,2) NOT NULL,
    end_date date NOT NULL,
    start_date date NOT NULL,
    usage_count integer DEFAULT 0 NOT NULL,
    usage_limit integer,
    created_at timestamp(6) with time zone,
    updated_at timestamp(6) with time zone,
    promotion_offer_id uuid NOT NULL,
    created_by character varying(255),
    description character varying(255),
    discount_type character varying(255) NOT NULL,
    name character varying(255) NOT NULL,
    promo_code character varying(255) NOT NULL,
    status character varying(255) NOT NULL,
    store_code character varying(255),
    CONSTRAINT promotion_offer_discount_type_check CHECK (((discount_type)::text = ANY (ARRAY[('PERCENT_LABOR'::character varying)::text, ('PERCENT_PARTS'::character varying)::text, ('FIXED_INVOICE'::character varying)::text]))),
    CONSTRAINT promotion_offer_status_check CHECK (((status)::text = ANY (ARRAY[('DRAFT'::character varying)::text, ('ACTIVE'::character varying)::text, ('INACTIVE'::character varying)::text, ('EXPIRED'::character varying)::text])))
);

CREATE TABLE public.restriction_override_audit (
    tenant_id uuid DEFAULT public.app_current_tenant() NOT NULL,
    policy_version integer NOT NULL,
    expires_at timestamp(6) with time zone NOT NULL,
    issued_at timestamp(6) with time zone NOT NULL,
    override_id uuid NOT NULL,
    product_id uuid NOT NULL,
    rule_id uuid NOT NULL,
    transaction_id uuid NOT NULL,
    actor character varying(255) NOT NULL,
    approved_by character varying(255),
    notes character varying(255),
    override_context character varying(255) NOT NULL,
    reason_code character varying(255) NOT NULL,
    status character varying(255) NOT NULL,
    CONSTRAINT restriction_override_audit_override_context_check CHECK (((override_context)::text = ANY (ARRAY[('BROWSE'::character varying)::text, ('QUOTE'::character varying)::text, ('CHECKOUT'::character varying)::text, ('INVOICE_FINALIZE'::character varying)::text, ('COMMIT_SALE'::character varying)::text]))),
    CONSTRAINT restriction_override_audit_status_check CHECK (((status)::text = ANY (ARRAY[('ISSUED'::character varying)::text, ('APPROVED'::character varying)::text, ('DENIED'::character varying)::text])))
);

CREATE TABLE public.restriction_rule (
    tenant_id uuid DEFAULT public.app_current_tenant() NOT NULL,
    active boolean NOT NULL,
    effective_from date NOT NULL,
    effective_to date,
    overrideable boolean NOT NULL,
    policy_version integer NOT NULL,
    created_at timestamp(6) with time zone,
    updated_at timestamp(6) with time zone,
    product_id uuid NOT NULL,
    rule_id uuid NOT NULL,
    location_tag character varying(255) NOT NULL,
    service_tag character varying(255) NOT NULL,
    CONSTRAINT restriction_rule_location_tag_check CHECK (((location_tag)::text = ANY (ARRAY[('ALL_LOCATIONS'::character varying)::text, ('RETAIL_STORE'::character varying)::text, ('WAREHOUSE'::character varying)::text, ('MOBILE_SERVICE'::character varying)::text, ('FRANCHISE'::character varying)::text, ('TEST_LOCATION'::character varying)::text]))),
    CONSTRAINT restriction_rule_service_tag_check CHECK (((service_tag)::text = ANY (ARRAY[('POS_SALE'::character varying)::text, ('WORKORDER'::character varying)::text, ('ESTIMATE'::character varying)::text, ('INVOICE'::character varying)::text, ('DELIVERY'::character varying)::text])))
);

