CREATE INDEX idx_base_price_product_currency_effective ON public.product_base_price USING btree (product_id, currency, effective_from, effective_to);

CREATE INDEX idx_location_override_product_location_effective ON public.location_price_override USING btree (product_id, location_id, effective_from, effective_to);

CREATE INDEX idx_tier_rule_product_tier_effective ON public.customer_tier_pricing_rule USING btree (product_id, customer_tier_id, effective_from, effective_to);

CREATE INDEX ix_labor_rate_scope ON public.labor_rate USING btree (location_id, operation_category, effective_from, effective_to);

CREATE INDEX ix_lra_scope ON public.labor_rate_adjustment USING btree (location_id, operation_category, effective_from, effective_to);

CREATE UNIQUE INDEX uq_base_price_open_window ON public.product_base_price USING btree (tenant_id, product_id, currency) WHERE (effective_to IS NULL);

CREATE UNIQUE INDEX ux_labor_rate_scope_start ON public.labor_rate USING btree (tenant_id, location_id, operation_category, effective_from) NULLS NOT DISTINCT;

CREATE UNIQUE INDEX ux_lra_scope_code_start ON public.labor_rate_adjustment USING btree (tenant_id, location_id, operation_category, adjustment_code, effective_from) NULLS NOT DISTINCT;

